import TurndownService from 'turndown';

import { removeLineBreaks } from 'proton-mail/helpers/string';
import { extractContentFromPtag, prepareConversionToHTML } from 'proton-mail/helpers/textToHtml';

const turndownService = new TurndownService({
    bulletListMarker: '-', // Use '-' instead of '*'
    hr: '---', // Use '---' instead of '***'
    headingStyle: 'atx', // Use '#' for headings
});

turndownService.addRule('strikethrough', {
    filter: ['del', 's', 'strike' as any], // 'strike' is deprecated, however the editor insert strike tag
    replacement: function (content) {
        return `~~${content}~~`;
    },
});

const escapeAttribute = (value: string) =>
    value.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const preservedAttributes = (node: HTMLElement, names: string[]) =>
    names
        .filter((name) => node.hasAttribute(name))
        .map((name) => ` ${name}="${escapeAttribute(node.getAttribute(name) || '')}"`)
        .join('');

// Markdown links and images cannot express HTML attributes. Keep the formatted ones
// as HTML so class and style survive a conversion back to HTML.
turndownService.addRule('formattedLink', {
    filter: (node) => node.nodeName === 'A' && (node.hasAttribute('class') || node.hasAttribute('style')),
    replacement: (content, node) => `<a${preservedAttributes(node, ['href', 'class', 'style'])}>${content}</a>`,
});

turndownService.addRule('formattedImage', {
    filter: (node) => node.nodeName === 'IMG' && (node.hasAttribute('class') || node.hasAttribute('style')),
    replacement: (_content, node) =>
        `<img${preservedAttributes(node, [
            'src',
            'alt',
            'class',
            'style',
            'proton-src',
            'data-embedded-img',
            'id',
        ])}>`,
});

export const fixNestedLists = (dom: Document): Document => {
    dom.querySelectorAll('ul, ol').forEach((list) => {
        const parent = list.parentElement;
        if (parent?.tagName !== 'UL' && parent?.tagName !== 'OL') {
            return;
        }

        const previousItem = list.previousElementSibling;
        if (previousItem?.tagName === 'LI') {
            previousItem.appendChild(list);
        } else {
            const item = dom.createElement('li');
            parent.insertBefore(item, list);
            item.appendChild(list);
        }
    });

    return dom;
};

const cleanMarkdown = (markdown: string): string => {
    let inFence = false;

    return markdown
        .split('\n')
        .map((line) => {
            const fence = /^([ \t]*)(`{3,}|~{3,})([ \t]*)(.*)$/.exec(line);
            if (fence) {
                inFence = !inFence;
                return `${fence[1]}${fence[2]}${fence[4]}`;
            }
            if (inFence) {
                return line;
            }

            // Keep the leading indentation: it defines list depth and may be
            // required for code within a list. Only normalize marker spacing.
            return line
                .replace(/^([ \t]*)([-+*]|\d+[.)])[ \t]+/, '$1$2 ')
                .replace(/^([ \t]*)(#{1,6})[ \t]+/, '$1$2 ')
                .replace(/^([ \t]*>)[ \t]+/, '$1 ');
        })
        .join('\n');
};

export const htmlToMarkdown = (dom: Document): string => {
    const markdown = turndownService.turndown(fixNestedLists(dom));
    const markdownCleaned = cleanMarkdown(markdown);
    return markdownCleaned;
};

// Using the same config and steps than what we do in textToHTML.
// This is formatting lists and other elements correctly, adding line separators etc...
export const markdownToHTML = (markdownContent: string, keepLineBreaks = false): string => {
    const html = prepareConversionToHTML(markdownContent, ['lheading', 'heading', 'code', 'fence', 'hr'], true);
    // Need to remove line breaks, we already have <br/> tag to separate lines
    const htmlCleaned = keepLineBreaks ? html : removeLineBreaks(html);
    /**
     * The capturing group includes negative lookup "(?!<p>)" in order to avoid nested problems.
     * Ex, this capture will be ignored : "<p>Hello</p><p>Hello again</p>""
     * Because it would have ended up with this result : "Hello</p><p>Hello again"
     */
    return extractContentFromPtag(htmlCleaned) || htmlCleaned;
};

